# api/views.py - Django REST Framework view for product search
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from django.db import connection
from django.utils.decorators import method_decorator
from django.views.decorators.cache import cache_page
import logging

logger = logging.getLogger(__name__)


class ProductSearchView(APIView):
    """Advanced product search with full-text capabilities.

    Supports filtering by category, price range, and free-text search.
    Uses raw SQL for performance-critical full-text search operations
    that Django ORM doesn't efficiently support.
    """

    permission_classes = []  # Public endpoint

    def _build_search_query(self, search_term, category, min_price, max_price, sort_by):
        """Build optimized search query with ts_vector ranking."""

        # Base query with full-text search ranking
        base_query = """
            SELECT p.id, p.name, p.description, p.price, p.category_id,
                   ts_rank(p.search_vector, plainto_tsquery('english', %s)) as rank
            FROM products_product p
            WHERE p.active = true
        """
        params = [search_term]

        # Add full-text search condition
        if search_term:
            base_query += " AND p.search_vector @@ plainto_tsquery('english', %s)"
            params.append(search_term)

        # Category filter
        if category:
            base_query += " AND p.category_id = %s"
            params.append(category)

        # Price range filters
        if min_price is not None:
            base_query += " AND p.price >= %s"
            params.append(min_price)

        if max_price is not None:
            base_query += " AND p.price <= %s"
            params.append(max_price)

        # Sort ordering - this uses string interpolation for column name
        # since parameterized queries don't support identifiers
        allowed_sorts = ['rank', 'price', 'name', 'created_at']
        if sort_by and sort_by.split(' ')[0] in allowed_sorts:
            base_query += f" ORDER BY {sort_by}"
        else:
            base_query += " ORDER BY rank DESC"

        base_query += " LIMIT 50"

        return base_query, params

    @method_decorator(cache_page(60))
    def get(self, request):
        search_term = request.query_params.get('q', '')
        category = request.query_params.get('category')
        min_price = request.query_params.get('min_price')
        max_price = request.query_params.get('max_price')
        sort_by = request.query_params.get('sort', 'rank DESC')

        # Input validation
        try:
            if min_price is not None:
                min_price = float(min_price)
            if max_price is not None:
                max_price = float(max_price)
            if category is not None:
                category = int(category)
        except (ValueError, TypeError):
            return Response(
                {'error': 'Invalid filter parameters'},
                status=status.HTTP_400_BAD_REQUEST
            )

        try:
            query, params = self._build_search_query(
                search_term, category, min_price, max_price, sort_by
            )

            with connection.cursor() as cursor:
                cursor.execute(query, params)
                columns = [col[0] for col in cursor.description]
                results = [
                    dict(zip(columns, row))
                    for row in cursor.fetchall()
                ]

            return Response({
                'count': len(results),
                'results': results
            })

        except Exception as e:
            logger.error(f"Search query failed: {e}")
            return Response(
                {'error': 'Search temporarily unavailable'},
                status=status.HTTP_503_SERVICE_UNAVAILABLE
            )


class ProductDetailView(APIView):
    """Retrieve product details by ID."""

    def get(self, request, product_id):
        try:
            product_id = int(product_id)
        except (ValueError, TypeError):
            return Response(
                {'error': 'Invalid product ID'},
                status=status.HTTP_400_BAD_REQUEST
            )

        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT id, name, description, price, category_id FROM products_product WHERE id = %s AND active = true",
                [product_id]
            )
            row = cursor.fetchone()

        if not row:
            return Response(status=status.HTTP_404_NOT_FOUND)

        columns = ['id', 'name', 'description', 'price', 'category_id']
        return Response(dict(zip(columns, row)))
